{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Extract REAPER Plugin UUID Map to JSON\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Reads reaper-vstplugins64.ini and reaper-clap-win64.ini from the REAPER resource path and writes reaper_plugin_map.json \u8212- a sorted map of plugin name to \{uid, filename, type\}.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Note: the scanned INI filenames are Windows-specific; on other platforms the script runs but reports that no plugins were found.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Generate Full Session Template (RPP)\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Builds a session RPP with a drum folder, instrument children, a reverb bus, sends, track colors and markers, using REAPER 7.x chunk formats. Writes auto_session_v2.rpp and an APPLY_FX_HERE.md note into a generated_assets folder next to the script. FX are applied at runtime \u8212- no fabricated binary presets.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Requires rpp_helpers.lua, which ReaPack installs alongside this script.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Generate Plugin Map Lua Module\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Reads reaper-vstplugins64.ini and reaper-clap-win64.ini from the REAPER resource path and writes plugin_map.lua (name -> \{uid, filename, type\}) into the REAPER resource path for dofile() consumption by other ReaScripts, e.g. SGM_Insert FX by Name from Plugin Map.lua.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Note: the scanned INI filenames are Windows-specific; on other platforms the script runs but reports that no plugins were found.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Generate REAPER Session Assets (RPP + EEL)\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Builds a valid auto_session_v1.rpp and clean_slate_reset.eel into a generated_assets folder next to the script, using a strict, balanced-node builder (unbalanced chunks are impossible by construction).\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Insert FX by Name from Plugin Map\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Prompts for a plugin name (from plugin_map.lua) and inserts it onto all selected tracks. Requires a partial/fuzzy name match; shows a sample of available plugins when nothing matches.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Run SGM_Generate Plugin Map Lua Module.lua first to build the map.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 Podcast Session Bootstrap\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Builds a podcast session: speaker tracks, music bed, SFX, dialogue + show buses, routing, colors, markers/regions, and stock Cockos FX chains (ReaComp, ReaLimit, ReaGate, ReaEQ \u8212- added by name, no binary presets).\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Idempotent: existing tracks/sends/markers are reused, not duplicated. Set CONFIG.dry_run = true at the top of the script to preview every planned action without touching the project.\par}
}
